/* Encrypted profile storage only. This is NOT a shielded spending wallet. */
(function(root){'use strict';
const VERSION=1,ITERATIONS=600000,CONTEXT=new TextEncoder().encode('NULLIS:LOCAL-PROFILE:1');
const subtle=()=>globalThis.crypto.subtle;
function encode(bytes){let text='';for(const byte of bytes)text+=String.fromCharCode(byte);return btoa(text)}
function decode(text,max){if(typeof text!=='string'||text.length>max||!/^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(text))throw Error('Invalid backup encoding');return Uint8Array.from(atob(text),c=>c.charCodeAt(0))}
function payload(value){if(!value||value.type!=='profile'||typeof value.owner!=='string'||!/^0x[0-9a-f]{40}$/.test(value.owner)||typeof value.username!=='string'||!/^[A-Za-z0-9_]{3,20}$/.test(value.username)||typeof value.photo!=='string'||value.photo.length>1000000||(value.photo!==''&&!/^data:image\/png;base64,[A-Za-z0-9+/=]+$/.test(value.photo))||!Number.isSafeInteger(value.createdAt)||value.createdAt<0)throw Error('Invalid profile data');const result={type:'profile',owner:value.owner,username:value.username,photo:value.photo,createdAt:value.createdAt};if(value.registryKey){if(typeof value.registryKey.publicKey!=='string'||value.registryKey.publicKey.length!==88||typeof value.registryKey.privateKey!=='string'||value.registryKey.privateKey.length>512||!value.registryKey.privateKey.length||!/^([A-Za-z0-9+/=]+)$/.test(value.registryKey.publicKey+value.registryKey.privateKey))throw Error('Invalid username ownership key');result.registryKey={publicKey:value.registryKey.publicKey,privateKey:value.registryKey.privateKey}}if(value.registeredName){if(!value.registryKey||value.registeredName!==value.username)throw Error('Registered username cannot change.');result.registeredName=value.registeredName}return result}
function validate(value){if(!value||value.format!=='nullis-encrypted-profile'||value.version!==VERSION||value.kdf!=='PBKDF2-SHA256'||value.cipher!=='AES-256-GCM'||value.iterations!==ITERATIONS)throw Error('Unsupported encrypted profile format');const salt=decode(value.salt,32),iv=decode(value.iv,24),ciphertext=decode(value.ciphertext,1500000);if(salt.length!==16||iv.length!==12||ciphertext.length<16)throw Error('Invalid encrypted profile');return {format:value.format,version:VERSION,kdf:value.kdf,iterations:ITERATIONS,cipher:value.cipher,salt:value.salt,iv:value.iv,ciphertext:value.ciphertext}}
async function derive(password,salt){if(typeof password!=='string'||password.length<12||password.length>1024)throw Error('Use a passphrase of 12–1024 characters.');const material=await subtle().importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);return subtle().deriveKey({name:'PBKDF2',hash:'SHA-256',iterations:ITERATIONS,salt},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function seal(key,data,salt){const iv=crypto.getRandomValues(new Uint8Array(12)),plaintext=new TextEncoder().encode(JSON.stringify(payload(data)));const encrypted=await subtle().encrypt({name:'AES-GCM',iv,additionalData:CONTEXT,tagLength:128},key,plaintext);plaintext.fill(0);return {format:'nullis-encrypted-profile',version:VERSION,kdf:'PBKDF2-SHA256',iterations:ITERATIONS,cipher:'AES-256-GCM',salt:encode(salt),iv:encode(iv),ciphertext:encode(new Uint8Array(encrypted))}}
async function create(password,data){data=payload(data);const salt=crypto.getRandomValues(new Uint8Array(16)),key=await derive(password,salt),envelope=await seal(key,data,salt);return {key,data,envelope}}
async function unlock(envelope,password,owner){envelope=validate(envelope);const key=await derive(password,decode(envelope.salt,32));let plain;try{plain=new Uint8Array(await subtle().decrypt({name:'AES-GCM',iv:decode(envelope.iv,24),additionalData:CONTEXT,tagLength:128},key,decode(envelope.ciphertext,1500000)))}catch{throw Error('Incorrect passphrase or damaged backup.')}
let data;try{data=payload(JSON.parse(new TextDecoder().decode(plain)))}finally{plain.fill(0)}if(data.owner!==owner.toLowerCase())throw Error('This profile belongs to a different connected wallet.');return {key,data,envelope}}
async function update(opened,data){data=payload(data);if(data.owner!==opened.data.owner)throw Error('Profile owner cannot change.');return {key:opened.key,data,envelope:await seal(opened.key,data,decode(opened.envelope.salt,32))}}
const api={create,unlock,update,validate,payload};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.NullisVault=api;
})(globalThis);
